/**
 * @file test/Unit/test_xbt_conformance.cpp
 * @brief Runs the Z3-verified conformance vectors against the Xbt hardware model.
 *
 * The vectors in verification/vectors/xbt_conformance.hpp are generated by
 * verification/gen_vectors.py from the *mathematical specification* -- never
 * from this model -- and that specification is proved equivalent to the
 * hardware in verification/verify_isa.py.
 *
 * So a failure here means one of:
 *   - the C++ model regressed,
 *   - the RTL model and the C++ model diverged,
 *   - the specification itself changed.
 *
 * This is the test that would also be pointed at an RTL simulation or an FPGA
 * bring-up: the vectors are the contract, not this file.
 */

#include "../../hw/xbt_alu_model.hpp"
#include "../../verification/vectors/xbt_conformance.hpp"

#include <cstdint>
#include <cstdio>
#include <string>

using namespace bt;
using namespace bt::hw;
using namespace bt::hw::conformance;

namespace {

int g_failures = 0;
long long g_checks = 0;

void fail(const std::string& op, long long index, const std::string& what) {
    std::printf("  FAIL %s[%lld]: %s\n", op.c_str(), index, what.c_str());
    ++g_failures;
}

void expect(bool cond, const std::string& op, long long i, const std::string& what) {
    ++g_checks;
    if (!cond) fail(op, i, what);
}

std::string hex64(std::uint64_t v) {
    char buf[32];
    std::snprintf(buf, sizeof buf, "0x%016llx", (unsigned long long)v);
    return std::string(buf);
}

/** 3**n as an integer, for small n. */
long long ipow3(int n) {
    long long r = 1;
    for (int i = 0; i < n; ++i) r *= 3;
    return r;
}

/** Decode one lane of a dual-rail word to a trit value, or 2 if invalid. */
int lane(TritWord64 w, int i) {
    bool p = (w.P >> i) & 1ULL;
    bool n = (w.N >> i) & 1ULL;
    if (p && n) return 2;               // invalid: no fourth trit
    return p ? 1 : (n ? -1 : 0);
}

void check_lane(const char* op, long long i, const char* which,
                TritWord64 got, int exp) {
    int g = lane(got, 0);
    if (g == 2) {
        fail(op, i, std::string(which) + " produced invalid dual-rail (P&N both set)");
    } else if (g != exp) {
        fail(op, i, std::string(which) + " expected " + std::to_string(exp) +
                    " got " + std::to_string(g));
    }
}

// -------------------------------------------------------------------------
// Scalar (single-trit) groups -- exhaustive
// -------------------------------------------------------------------------

void test_btha_scalar() {
    for (size_t i = 0; i < BTHA_count(); ++i) {
        const auto& c = BTHA_cases()[i];
        TritWord64 a = TritWord64(c.a == 1 ? 1ULL : 0ULL, c.a == -1 ? 1ULL : 0ULL);
        TritWord64 b = TritWord64(c.b == 1 ? 1ULL : 0ULL, c.b == -1 ? 1ULL : 0ULL);
        AdderOutput r = BTHA(a, b);
        check_lane("BTHA", (long long)i, "sum", r.Sum, (int)c.sum);
        check_lane("BTHA", (long long)i, "carry", r.Carry, (int)c.carry);
    }
}

void test_btfa_scalar() {
    for (size_t i = 0; i < BTFA_count(); ++i) {
        const auto& c = BTFA_cases()[i];
        TritWord64 a = TritWord64(c.a == 1 ? 1ULL : 0ULL, c.a == -1 ? 1ULL : 0ULL);
        TritWord64 b = TritWord64(c.b == 1 ? 1ULL : 0ULL, c.b == -1 ? 1ULL : 0ULL);
        TritWord64 d = TritWord64(c.d == 1 ? 1ULL : 0ULL, c.d == -1 ? 1ULL : 0ULL);
        AdderOutput r = BTFA(a, b, d);
        check_lane("BTFA", (long long)i, "sum", r.Sum, (int)c.sum);
        check_lane("BTFA", (long long)i, "carry", r.Carry, (int)c.carry);
    }
}

void test_neg_scalar() {
    for (size_t i = 0; i < NEG_count(); ++i) {
        const auto& c = NEG_cases()[i];
        TritWord64 a = TritWord64(c.a == 1 ? 1ULL : 0ULL, c.a == -1 ? 1ULL : 0ULL);
        TritWord64 r = TritWord64(a.N, a.P);
        check_lane("NEG", (long long)i, "neg", r, (int)c.neg);
    }
}

/**
 * CSAMAC: the documented contract is rd + (rs1 * rs2) == sum + 3*carry.
 * The accumulator operand is the destination register.
 */
void test_csamac_scalar() {
    for (size_t i = 0; i < CSAMAC_count(); ++i) {
        const auto& c = CSAMAC_cases()[i];
        RiscvXbtCoprocessor cpu;
        cpu.treg[1] = TritWord64(c.rs1 == 1 ? 1ULL : 0ULL, c.rs1 == -1 ? 1ULL : 0ULL);
        cpu.treg[2] = TritWord64(c.rs2 == 1 ? 1ULL : 0ULL, c.rs2 == -1 ? 1ULL : 0ULL);
        cpu.treg[3] = TritWord64(c.rd == 1 ? 1ULL : 0ULL, c.rd == -1 ? 1ULL : 0ULL);
        // xbt.csamac t3, t1, t2   ->   t3 = t3 + (t1 * t2)
        cpu.execute(encode_xbt_r(0, 2, 1, static_cast<std::uint8_t>(XbtFunct3::CSAMAC), 3));
        check_lane("CSAMAC", (long long)i, "sum", cpu.treg[3], (int)c.sum);
        check_lane("CSAMAC", (long long)i, "carry", cpu.last_carry, (int)c.carry);
    }
}

void test_unpack243() {
    for (size_t i = 0; i < UNPACK243_count(); ++i) {
        const auto& c = UNPACK243_cases()[i];
        if (!c.valid) {
            // Out-of-range bytes must be rejected, not silently decoded.
            TritWord64 r = rtl_base243_decoder(static_cast<std::uint8_t>(c.byte));
            expect(r.P == 0 && r.N == 0, "UNPACK243", (long long)i,
                   "byte >= 243 must decode to zero (rejected)");
            continue;
        }
        RiscvXbtCoprocessor cpu;
        cpu.xreg[15] = c.byte;
        cpu.execute(encode_xbt_r(0, 0, 15,
                                 static_cast<std::uint8_t>(XbtFunct3::UNPACK243), 16));
        TritWord64 r = cpu.treg[16];
        expect(r.isValid(), "UNPACK243", (long long)i, "output rails must not overlap");
        // value == byte - 121 over 5 trits
        long long v = 0;
        for (int k = 0; k < 5; ++k) v += (long long)lane(r, k) * (long long)ipow3(k);
        expect(v == c.value, "UNPACK243", (long long)i,
               "byte " + std::to_string(c.byte) + " expected " +
               std::to_string(c.value) + " got " + std::to_string(v));
        // trits beyond 5 must stay zero
        bool upper_clean = true;
        for (int k = 5; k < 64; ++k) if (lane(r, k) != 0) upper_clean = false;
        expect(upper_clean, "UNPACK243", (long long)i, "trits 5..63 must be zero");
    }
}

// -------------------------------------------------------------------------
// Word-level groups
// -------------------------------------------------------------------------

void test_ksadd_word() {
    for (size_t i = 0; i < KSADD_count(); ++i) {
        const auto& c = KSADD_cases()[i];
        TritWord64 a = TritWord64((std::uint64_t)c.a_p, (std::uint64_t)c.a_n);
        TritWord64 b = TritWord64((std::uint64_t)c.b_p, (std::uint64_t)c.b_n);
        KoggeStoneResult64 r = rtl_kogge_stone_adder64(a, b);
        expect(r.sum.P == (std::uint64_t)c.sum_p && r.sum.N == (std::uint64_t)c.sum_n,
               "KSADD", (long long)i,
               "sum expected " + hex64((std::uint64_t)c.sum_p) + "/" +
               hex64((std::uint64_t)c.sum_n) + " got " + hex64(r.sum.P) + "/" +
               hex64(r.sum.N));
        int cout = (r.cout == Trit::Pos) ? 1 : ((r.cout == Trit::Neg) ? -1 : 0);
        expect(cout == (int)c.cout, "KSADD", (long long)i,
               "cout expected " + std::to_string((int)c.cout) + " got " +
               std::to_string(cout));
    }
}

void test_dot64_word() {
    for (size_t i = 0; i < DOT64_count(); ++i) {
        const auto& c = DOT64_cases()[i];
        TritWord64 a = TritWord64((std::uint64_t)c.a_p, (std::uint64_t)c.a_n);
        TritWord64 b = TritWord64((std::uint64_t)c.b_p, (std::uint64_t)c.b_n);
        std::int64_t got = dotProduct64(a, b);
        expect(got == c.acc, "DOT64", (long long)i,
               "expected " + std::to_string((long long)c.acc) + " got " +
               std::to_string((long long)got));
    }
}

void test_neg_word() {
    for (size_t i = 0; i < NEG_WORD_count(); ++i) {
        const auto& c = NEG_WORD_cases()[i];
        TritWord64 a = TritWord64((std::uint64_t)c.a_p, (std::uint64_t)c.a_n);
        TritWord64 r = TritWord64(a.N, a.P);
        expect(r.P == (std::uint64_t)c.neg_p && r.N == (std::uint64_t)c.neg_n,
               "NEG_WORD", (long long)i, "negation must swap P and N rails");
    }
}

void test_adder_words() {
    for (size_t i = 0; i < BTHA_WORD_count(); ++i) {
        const auto& c = BTHA_WORD_cases()[i];
        TritWord64 a = TritWord64((std::uint64_t)c.a_p, (std::uint64_t)c.a_n);
        TritWord64 b = TritWord64((std::uint64_t)c.b_p, (std::uint64_t)c.b_n);
        AdderOutput r = BTHA(a, b);
        expect(r.Sum.P == (std::uint64_t)c.sum_p && r.Sum.N == (std::uint64_t)c.sum_n,
               "BTHA_WORD", (long long)i, "sum mismatch");
        expect(r.Carry.P == (std::uint64_t)c.carry_p && r.Carry.N == (std::uint64_t)c.carry_n,
               "BTHA_WORD", (long long)i, "carry mismatch");
    }
    for (size_t i = 0; i < BTFA_WORD_count(); ++i) {
        const auto& c = BTFA_WORD_cases()[i];
        TritWord64 a = TritWord64((std::uint64_t)c.a_p, (std::uint64_t)c.a_n);
        TritWord64 b = TritWord64((std::uint64_t)c.b_p, (std::uint64_t)c.b_n);
        AdderOutput r = BTFA(a, b, TritWord64(0, 0));
        expect(r.Sum.P == (std::uint64_t)c.sum_p && r.Sum.N == (std::uint64_t)c.sum_n,
               "BTFA_WORD", (long long)i, "sum mismatch");
        expect(r.Carry.P == (std::uint64_t)c.carry_p && r.Carry.N == (std::uint64_t)c.carry_n,
               "BTFA_WORD", (long long)i, "carry mismatch");
    }
}

/** Word-level CSAMAC: rd + (rs1*rs2), checked per lane against the vectors. */
void test_csamac_word() {
    for (size_t i = 0; i < CSAMAC_WORD_count(); ++i) {
        const auto& c = CSAMAC_WORD_cases()[i];
        RiscvXbtCoprocessor cpu;
        cpu.treg[1] = TritWord64((std::uint64_t)c.a_p, (std::uint64_t)c.a_n);
        cpu.treg[2] = TritWord64((std::uint64_t)c.b_p, (std::uint64_t)c.b_n);
        cpu.treg[3] = TritWord64(0, 0);   // accumulator starts at zero
        cpu.execute(encode_xbt_r(0, 2, 1, static_cast<std::uint8_t>(XbtFunct3::CSAMAC), 3));
        expect(cpu.treg[3].P == (std::uint64_t)c.sum_p &&
               cpu.treg[3].N == (std::uint64_t)c.sum_n,
               "CSAMAC_WORD", (long long)i, "sum mismatch");
        expect(cpu.last_carry.P == (std::uint64_t)c.carry_p &&
               cpu.last_carry.N == (std::uint64_t)c.carry_n,
               "CSAMAC_WORD", (long long)i, "carry mismatch");
    }
}

} // namespace

int main() {
    std::printf("Xbt conformance suite (Z3-verified vectors)\n");
    std::printf("===========================================\n");

    std::printf("  BTHA         %6zu cases\n", BTHA_count());
    std::printf("  BTFA         %6zu cases\n", BTFA_count());
    std::printf("  NEG          %6zu cases\n", NEG_count());
    std::printf("  CSAMAC       %6zu cases\n", CSAMAC_count());
    std::printf("  UNPACK243    %6zu cases\n", UNPACK243_count());
    std::printf("  KSADD        %6zu cases\n", KSADD_count());
    std::printf("  DOT64        %6zu cases\n", DOT64_count());
    std::printf("  NEG_WORD     %6zu cases\n", NEG_WORD_count());
    std::printf("  BTHA_WORD    %6zu cases\n", BTHA_WORD_count());
    std::printf("  BTFA_WORD    %6zu cases\n", BTFA_WORD_count());
    std::printf("  CSAMAC_WORD  %6zu cases\n", CSAMAC_WORD_count());
    std::printf("\n");

    test_btha_scalar();
    test_btfa_scalar();
    test_neg_scalar();
    test_csamac_scalar();
    test_unpack243();
    test_ksadd_word();
    test_dot64_word();
    test_neg_word();
    test_adder_words();
    test_csamac_word();

    std::printf("\n%lld checks, %d failure(s)\n", g_checks, g_failures);
    if (g_failures) {
        std::printf("XBT CONFORMANCE: FAILED\n");
        return 1;
    }
    std::printf("XBT CONFORMANCE: PASSED\n");
    return 0;
}
